/* edax:command_mark_published */
DELETE FROM "public"."edax_command_outbox"
WHERE id IN (SELECT jsonb_array_elements_text(($1::text)::jsonb))

/* edax:command_unpublished_count */
SELECT count(*)
FROM "public"."edax_command_outbox"

/* edax:event_mark_published */
DELETE FROM "public"."edax_event_outbox"
WHERE event_id IN (SELECT jsonb_array_elements_text(($1::text)::jsonb))

/* edax:event_unpublished_count */
SELECT count(*)
FROM "public"."edax_event_outbox"

/* edax:ledger_delete */
DELETE FROM "public"."edax_ledger"
WHERE key = $1::text
